function setup() {
  createCanvas(500, 700, SVG);
  stroke(32);
  // noLoop() removed for animation
}

function draw() {
	background(222);
  const MAR = 50;
	const ww = 100;
	strokeWeight(1);
	noFill()

	// horizontal lines: hills
	for (let S=1, y = MAR; y < height - MAR; y += S) {
		S = map(y, 0, height, 1, 10);
		const zf = pow(sin(y/height*PI), 2) * height*0.65; // map(y, 0, height, 1, 200);
		// line(MAR, y, width-MAR, y)
		beginShape();
		for (let x = MAR; x < width - MAR; x += 5) {
			const xf = pow(sin(x/width*PI), 2);
			const z = noise(12.3 + x/123, 23.4 + y/231, frameCount) * zf * xf;
			vertex(x, y - z);
		}
		endShape();
	}

	// vertical lines: perspective
	const SP = 5;
	let numDebug = 2;
	for (let x = MAR+SP; x < width-MAR-SP; x += SP) {
		const d = width/2 - x;
		let xx = width/2 - d*2.186;
		let yy = height-MAR;
		if (xx < MAR) {
			const f = abs(x-MAR)/abs(x-xx);
			xx = MAR;
			yy = lerp(MAR, height-MAR, f);
		} else if (xx > width-MAR) {
			var f = abs(width-MAR-x)/abs(xx-x);
			xx = width-MAR;
			yy = lerp(MAR, height-MAR, f);
		}
		line(x, MAR, xx, yy); // width/2 - d*2.186, height-MAR);
	}
}

function mousePressed() {
	if (mouseButton === LEFT) redraw();
}

function keyPressed() {
	if (key === 's' || key === 'S') {
		save("mySketch.svg"); // Save the canvas as SVG
	}
}
